<?php
/**
 * core/ApiPolicy.php — central authorisation for panel API actions and CSV exports (2.1.5, risk R-02).
 *
 * Before 2.1.5 page permissions (Auth::canAccess) were checked only when a page was rendered;
 * the 430 API actions behind those pages had ad-hoc checks or none, so any logged-in operator
 * could call e.g. bulk-send, campaign or automation actions of pages hidden from them.
 *
 * Rule: API access = page access. An action may be called by a user allowed to open at least
 * one page whose UI uses it (core/ApiPolicy.map.php, generated by tools/gen_api_policy.php).
 * Administrators (and the read-only viewer, which core/Viewer.php gates separately) pass.
 * Actions no UI uses, and actions missing from the map, are administrators-only.
 * Existing per-action checks inside handlers remain in force; this is an additional outer gate.
 *
 * Escape hatch: eb_settings `security.api_authz` = 'monitor' logs would-be denials and allows.
 */
final class ApiPolicy
{
    /** ?export=type → pages (mirror of the pages that offer the export) */
    const EXPORTS = [
        'customers'          => ['persons'],
        'messages'           => ['inbox'],
        'notice_leads'       => ['notices'],
        'analytics_sessions' => ['analytics'],
    ];

    const DENY_MSG = 'دسترسی به این بخش برای حساب شما فعال نیست؛ از مدیر بخواهید دسترسی صفحه‌ی مربوط را بدهد.';

    private static ?array $map = null;

    public static function map(): array
    {
        if (self::$map === null) self::$map = require __DIR__ . '/ApiPolicy.map.php';
        return self::$map;
    }

    /**
     * Pure decision. $pages: ['*'] | [page…] | [] | null (unknown action).
     * @param callable(string):bool $canAccess
     * @return array{allow:bool, reason:string}
     */
    public static function decide(?array $pages, bool $isAdmin, callable $canAccess): array
    {
        if ($isAdmin) return ['allow' => true, 'reason' => 'admin'];
        if ($pages === null) return ['allow' => false, 'reason' => 'unknown_action'];
        if (in_array('*', $pages, true)) return ['allow' => true, 'reason' => 'any_user'];
        if (!$pages) return ['allow' => false, 'reason' => 'admin_only'];
        foreach ($pages as $p) if ($canAccess($p)) return ['allow' => true, 'reason' => 'page:' . $p];
        return ['allow' => false, 'reason' => 'no_page_access'];
    }

    public static function decideApi(string $action, bool $isAdmin, callable $canAccess): array
    {
        return self::decide(self::map()[$action] ?? null, $isAdmin, $canAccess);
    }

    public static function decideExport(string $type, bool $isAdmin, callable $canAccess): array
    {
        return self::decide(self::EXPORTS[$type] ?? null, $isAdmin, $canAccess);
    }

    private static function monitorOnly(): bool
    {
        try {
            $r = Database::one("SELECT v FROM eb_settings WHERE k = 'security.api_authz'");
            return strtolower(trim((string)($r['v'] ?? ''))) === 'monitor';
        } catch (Throwable $e) {
            return false;   // fail closed
        }
    }

    private static function gate(array $d, string $what): bool
    {
        if ($d['allow']) return true;
        $monitor = self::monitorOnly();
        error_log('[elanban authz] ' . ($monitor ? 'WOULD DENY (monitor)' : 'DENY') . " $what user=" . (int)Auth::id()
            . ' role=' . (string)Auth::role() . ' reason=' . $d['reason']);
        return $monitor;
    }

    /** Called in index.php before api/handler.php. Exits with 403 JSON when denied. */
    public static function enforceApi(string $action): void
    {
        $d = self::decideApi($action, Auth::isAdmin(), [Auth::class, 'canAccess']);
        if (self::gate($d, "api=$action")) return;
        http_response_code(403);
        header('Content-Type: application/json; charset=utf-8');
        exit(json_encode(['ok' => false, 'error' => self::DENY_MSG, 'code' => 'forbidden'], JSON_UNESCAPED_UNICODE));
    }

    /** Called in index.php before api/export.php. */
    public static function enforceExport(string $type): void
    {
        $d = self::decideExport($type, Auth::isAdmin(), [Auth::class, 'canAccess']);
        if (self::gate($d, "export=$type")) return;
        http_response_code(403);
        header('Content-Type: text/plain; charset=utf-8');
        exit(self::DENY_MSG);
    }
}
